candidates.raw:
size_t i;
int invalid = 0;
double speeds[4];
double cluster_max = 0.0;
double release = wo_config.release_rad_s;
double warn = wo_config.warn_rad_s;
double trip = wo_config.trip_rad_s;
double derate = wo_config.derate_torque_nm;
double brake = wo_config.brake_torque_nm;
double slew = wo_config.torque_slew_nm_per_cycle;
double dt = wo_config.dt_s;
unint32 rel_cyc = wo_config.release_cycles;
unint32 min_brake = wo_config.minimum_brake_cycles;
unint32 cool_cyc = wo_config.cooldown_cycles;

if (wo_state.mode == WO_FAULT) {
    for (i = 0; i < 4U; i++) {
        wo_state.previous_wheel_torque_nm[i] = 0.0;
        wo_output.wheel_torque_nm[i] = 0.0;
    }
    wo_output.mode = WO_FAULT;
    wo_output.clean = wo_state.clean;
    wo_output.elapsed = wo_state.elapsed;
    wo_output.limited_mask = 0U;
    wo_output.maximum_speed_rad_s = 0.0;
    wo_output.brake_power_w = 0.0;
    wo_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wo_output.momentum_norm_nms = 0.0;
    wo_output.dissipated_energy_j = wo_state.dissipated_energy_j;
    return;
}

if ((wo_input.wheels == NULL) || (wo_input.wheel_count != 4U))
    invalid = 1;
if ((wo_input.enable != 0) && (wo_input.enable != 1))
    invalid = 1;
if ((!isfinite(release)) || (!isfinite(warn)) || (!isfinite(trip)) ||
    (!(release >= 0.0)) || (!(release < warn)) || (!(warn < trip)))
    invalid = 1;
if ((!isfinite(derate)) || (!isfinite(brake)) || (!isfinite(slew)) || (!isfinite(dt)) ||
    (!(derate > 0.0)) || (!(brake > 0.0)) || (!(slew > 0.0)) || (!(dt > 0.0)))
    invalid = 1;
if (rel_cyc < 1U || rel_cyc > 100U || min_brake < 1U || min_brake > 100U ||
    cool_cyc < 1U || cool_cyc > 100U)
    invalid = 1;
if (brake < derate)
    invalid = 1;

if (!invalid) {
    for (i = 0; i < 4U; i++) {
        if ((!isfinite(wo_input.wheels[i].inertia_kg_m2)) ||
            (!isfinite(wo_input.wheels[i].speed_rad_s)) ||
            (wo_input.wheels[i].inertia_kg_m2 < 0.0) ||
            (!adcs_is_finite_vec3(&wo_input.wheels[i].axis_body)))
            invalid = 1;
        if (invalid) break;
        if (adcs_vec3_norm(&wo_input.wheels[i].axis_body) <= ADCS_EPS_NORM)
            invalid = 1;
        if (invalid) break;
    }
}

if (invalid) {
    wo_state.mode = WO_FAULT;
    for (i = 0; i < 4U; i++) {
        wo_state.previous_wheel_torque_nm[i] = 0.0;
        wo_output.wheel_torque_nm[i] = 0.0;
    }
    wo_output.mode = WO_FAULT;
    wo_output.limited_mask = 0U;
    wo_output.maximum_speed_rad_s = 0.0;
    wo_output.brake_power_w = 0.0;
    wo_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wo_output.momentum_norm_nms = 0.0;
    wo_output.dissipated_energy_j = wo_state.dissipated_energy_j;
    wo_output.clean = wo_state.clean;
    wo_output.elapsed = wo_state.elapsed;
    return;
}

if (wo_input.enable == 0) {
    wo_state.mode = WO_NORMAL;
    wo_state.clean = 0U;
    wo_state.elapsed = 0U;
    wo_state.dissipated_energy_j = 0.0;
    for (i = 0; i < 4U; i++) {
        wo_state.previous_wheel_torque_nm[i] = 0.0;
        wo_output.wheel_torque_nm[i] = 0.0;
    }
    wo_output.mode = WO_NORMAL;
    wo_output.clean = 0U;
    wo_output.elapsed = 0U;
    wo_output.limited_mask = 0U;
    wo_output.maximum_speed_rad_s = 0.0;
    wo_output.brake_power_w = 0.0;
    wo_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wo_output.momentum_norm_nms = 0.0;
    wo_output.dissipated_energy_j = 0.0;
    return;
}

{
    adcs_vec3_t h;
    adcs_status_t st = adcs_wheel_momentum(wo_input.wheels, 4U, &h);
    if (st != ADCS_OK || !adcs_is_finite_vec3(&h)) {
        wo_state.mode = WO_FAULT;
        for (i = 0; i < 4U; i++) {
            wo_state.previous_wheel_torque_nm[i] = 0.0;
            wo_output.wheel_torque_nm[i] = 0.0;
        }
        wo_output.mode = WO_FAULT;
        wo_output.clean = wo_state.clean;
        wo_output.elapsed = wo_state.elapsed;
        wo_output.limited_mask = 0U;
        wo_output.maximum_speed_rad_s = 0.0;
        wo_output.brake_power_w = 0.0;
        wo_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
        wo_output.momentum_norm_nms = 0.0;
        wo_output.dissipated_energy_j = wo_state.dissipated_energy_j;
        return;
    }
    wo_output.momentum_nms = h;
    wo_output.momentum_norm_nms = adcs_vec3_norm(&h);
}

for (i = 0; i < 4U; i++) {
    speeds[i] = wo_input.wheels[i].speed_rad_s;
    if (fabs(speeds[i]) > cluster_max)
        cluster_max = fabs(speeds[i]);
}
wo_output.maximum_speed_rad_s = cluster_max;

{
    int mode_changed = 0;

    if (wo_state.mode == WO_NORMAL) {
        if (cluster_max >= trip) {
            wo_state.mode = WO_BRAKE;
            mode_changed = 1;
        } else if (cluster_max >= warn) {
            wo_state.mode = WO_DERATE;
            mode_changed = 1;
        }
    } else if (wo_state.mode == WO_DERATE) {
        if (cluster_max >= trip) {
            wo_state.mode = WO_BRAKE;
            mode_changed = 1;
        } else if (cluster_max <= release) {
            wo_state.clean += 1U;
            if (wo_state.clean >= rel_cyc) {
                wo_state.mode = WO_NORMAL;
                mode_changed = 1;
            }
        } else {
            wo_state.clean = 0U;
        }
    } else if (wo_state.mode == WO_BRAKE) {
        if (wo_state.elapsed >= min_brake) {
            if (cluster_max <= release) {
                wo_state.clean += 1U;
                if (wo_state.clean >= rel_cyc) {
                    wo_state.mode = WO_COOLDOWN;
                    mode_changed = 1;
                }
            } else {
                wo_state.clean = 0U;
            }
        } else {
            wo_state.clean = 0U;
        }
    } else if (wo_state.mode == WO_COOLDOWN) {
        if (cluster_max >= trip) {
            wo_state.mode = WO_BRAKE;
            mode_changed = 1;
        } else if (wo_state.elapsed >= cool_cyc) {
            wo_state.mode = WO_NORMAL;
            mode_changed = 1;
        }
    } else {
        wo_state.mode = WO_FAULT;
    }

    if (mode_changed) {
        wo_state.clean = 0U;
        wo_state.elapsed = 0U;
    } else {
        wo_state.elapsed += 1U;
    }
}

{
    double desired[4];
    for (i = 0; i < 4U; i++) {
        double w = speeds[i];
        double aw = fabs(w);
        desired[i] = 0.0;
        if (wo_state.mode == WO_DERATE) {
            if (aw > release) {
                double mag = derate * (aw - release) / (trip - release);
                if (mag > derate) mag = derate;
                desired[i] = (w > 0.0) ? -mag : mag;
            }
        } else if (wo_state.mode == WO_BRAKE) {
            if (aw > 0.0) {
                desired[i] = (w > 0.0) ? -brake : brake;
            }
        }
    }

    wo_output.limited_mask = 0U;
    for (i = 0; i < 4U; i++) {
        double cmd = desired[i];
        double prev = wo_state.previous_wheel_torque_nm[i];
        double delta = cmd - prev;
        double limited = cmd;
        if (delta > slew) {
            limited = prev + slew;
            wo_output.limited_mask |= (unint32)(1U << i);
        } else if (delta < -slew) {
            limited = prev - slew;
            wo_output.limited_mask |= (unint32)(1U << i);
        }
        wo_output.wheel_torque_nm[i] = limited;
        wo_state.previous_wheel_torque_nm[i] = limited;
    }
}

{
    double power = 0.0;
    for (i = 0; i < 4U; i++) {
        power += -wo_output.wheel_torque_nm[i] * speeds[i];
    }
    wo_output.brake_power_w = power;
    wo_state.dissipated_energy_j += -power * dt;
    wo_output.dissipated_energy_j = wo_state.dissipated_energy_j;
}

wo_output.mode = wo_state.mode;
wo_output.clean = wo_state.clean;
wo_output.elapsed = wo_state.elapsed;

